function isSuppliedIcon(name: IconName): name is SuppliedIconName {
  return (
    name === "arrow-left" ||
    name === "lock" ||
    name === "part-category" ||
    name === "sidebar-dashboard" ||
    name === "sidebar-garage" ||
    name === "sidebar-history" ||
    name === "sidebar-search" ||
    name === "sidebar-settings" ||
    name === "sidebar-sync" ||
    name === "sidebar-users"
  );
}

